"""궁합 엔진 4축 테스트."""
from app.engine.calculator import calculate_saju
from app.engine.compatibility import compute_compatibility
from app.semantic.tagger import build_semantic_profile


def _profile(birth_date, birth_time, gender="M", mode="exact", city="seoul"):
    kwargs = dict(
        birth_date=birth_date,
        birth_location=city,
        correction_mode="lmt",
        jasi_boundary=23,
        gender=gender,
        birth_time_mode=mode,
    )
    if mode == "exact":
        kwargs["birth_time"] = birth_time
    r = calculate_saju(**kwargs)
    return build_semantic_profile(r)


P1974 = _profile("1974-02-24", "05:30:00")            # 丙 일간, 火 강
P1990 = _profile("1990-05-05", "14:30:00", gender="F") # 庚 일간, 金 강
P2005 = _profile("2005-08-15", "10:00:00", gender="F") # 부드러운 쪽


def test_all_axes_present():
    r = compute_compatibility(P1974, P1990)
    assert set(r["axes"].keys()) == {"elements", "day_master", "ten_gods", "sinsal"}
    assert set(r["overall"].keys()) == {"score", "grade"}


def test_scores_in_range():
    r = compute_compatibility(P1974, P1990)
    for k in ("elements", "day_master", "ten_gods", "sinsal"):
        s = r["axes"][k]["score"]
        assert -1.0 <= s <= 1.0, f"{k} score out of range: {s}"
    assert -1.0 <= r["overall"]["score"] <= 1.0


def test_grade_mapping():
    r = compute_compatibility(P1974, P1990)
    valid = {"PEAK", "FAVORABLE", "NEUTRAL", "CAUTION", "CHALLENGING"}
    assert r["overall"]["grade"] in valid
    for k in ("elements", "day_master", "ten_gods", "sinsal"):
        assert r["axes"][k]["grade"] in valid


def test_symmetry_of_pair_inputs():
    """A→B 와 B→A 는 동일한 overall 을 내야 함."""
    r1 = compute_compatibility(P1974, P1990)
    r2 = compute_compatibility(P1990, P1974)
    assert r1["overall"]["score"] == r2["overall"]["score"]


def test_day_only_input():
    """day_only 모드에서도 궁합 계산이 실패하지 않아야."""
    p_do = _profile("1974-02-24", None, mode="day_only")
    r = compute_compatibility(p_do, P1990)
    assert "overall" in r
    assert "day_master" in r["axes"]


def test_self_compatibility_neutral():
    """같은 사람과의 궁합 — 대부분 축은 self 가 아니라 정상 계산."""
    r = compute_compatibility(P1974, P1974)
    # elements: 자기 자신과 같음 → tension 가능성 (같은 dominant)
    # 정확한 값을 강제하지는 않고, 계산이 완료되면 OK
    assert "overall" in r


def test_shared_sinsal_axis_defined():
    """sinsal 축이 항상 shared 필드를 반환."""
    r = compute_compatibility(P1974, P1990)
    assert "shared" in r["axes"]["sinsal"]
    assert isinstance(r["axes"]["sinsal"]["shared"], list)


